UPDATE sn_line_count SET gen_count = GREATEST(gen_count - #{n}, 0), alloc_count = GREATEST(alloc_count - #{a}, 0),
  own_generated = GREATEST(own_generated - #{n}, 0), updated_at = #{now}
WHERE bill_no = #{billNo} AND seq = #{seq}

mapper.select:
SELECT del_no, MIN(sn) start_sn, MAX(sn) end_sn, COUNT(*) qty, MIN(deleted_by) deleted_by,
  MIN(deleted_at) deleted_at, MIN(reason) reason, GROUP_CONCAT(DISTINCT bill_no ORDER BY bill_no) bills
FROM sn_item_deleted WHERE pi_no = #{pi} GROUP BY del_no ORDER BY MIN(deleted_at) DESC, del_no DESC LIMIT #{limit}
